package pe.ganadoconecta.modulos.reproduccion.aplicacion;import java.util.*;import pe.ganadoconecta.modulos.ganado.aplicacion.AutorizarLecturaGanaderia;import pe.ganadoconecta.modulos.reproduccion.dominio.Parto;public final class ListarPartos{private final AutorizarLecturaGanaderia auth;private final RepositorioPartos repo;public ListarPartos(AutorizarLecturaGanaderia a,RepositorioPartos r){auth=a;repo=r;}public List<Parto> ejecutar(UUID actor,UUID g,UUID madre){auth.autorizar(actor,g);return repo.listar(g,madre);}}
